{
  "pick": 3,
  "name_zh": "寒流終結式",
  "concept": "匯聚連綿攻勢後的最後一擊，將積累的勢能化作刺骨的嚴寒。",
  "cast_flavor": "將所有蓄勢的動作凝結成一抹寒光，徹底凍結敵人的身形。"
}

{
  "pick": 3,
  "name_zh": "碎冰終結",
  "concept": "將先前所有連綿攻勢匯聚於一點，釋放積累的勢能。",
  "cast_flavor": "隨著連擊節奏的最後一次迸發，將凝結的寒意徹底釋放。"
}

{
  "pick": 0,
  "name_zh": "大地怒吼",
  "concept": "將積聚的憤怒轉化為厚實的岩層衝擊。",
  "cast_flavor": "隨著咆哮聲響，地面裂開並隆起巨大的石柱。"
}

{
  "pick": 0,
  "name_zh": "怒火岩爆",
  "concept": "將積聚的憤怒轉化為厚實的岩層衝擊。",
  "cast_flavor": "隨著咆哮聲響，地面裂開並迸發出巨大的石柱。"
}

{
  "pick": 0,
  "name_zh": "重擊標記",
  "concept": "以強大的衝擊力將敵人的位置鎖定在地面。 ",
  "cast_flavor": "重壓落下的瞬間，地面裂開的縫隙將目標徹底釘死。"
}

{
  "pick": 1,
  "name_zh": "暗影連鎖炸彈",
  "concept": "在敵人周身點燃不穩定的暗影，並使其行蹤暴露於視野之中。",
  "cast_flavor": "暗影在目標身上不安地跳動，隨即引發連鎖的爆裂。"
}

{
  "pick": 1,
  "name_zh": "影縛陷阱",
  "concept": "將不穩定的暗影附著於敵人身上，隨即引發連鎖的爆裂。",
  "cast_flavor": "暗影在目標身上不安地跳動，隨即引發連鎖的爆裂。"
}

{
  "pick": 0,
  "name_zh": "寒霜撞擊",
  "concept": "以極寒之氣凍結目標並產生劇烈衝擊。",
  "cast_flavor": "寒流瞬間將空氣凝結，將敵人凍結在冰層中。"
}

{
  "pick": 0,
  "name_zh": "寒霜撞擊",
  "concept": "凍結空氣並將目標強行拉向施放者。",
  "cast_flavor": "冰層迅速蔓延並在撞擊中將敵人拽向前方。"
}

{
  "pick": 0,
  "name_zh": "霜結之衝",
  "concept": "透過寒意凝聚並將敵人拉向目標位置。",
  "cast_flavor": "冰層在撞擊瞬間擴張，將敵人拽向冰封點。"
}

{
  "pick": 1,
  "name_zh": "迴旋風紋",
  "concept": "於空氣中刻劃出流動的氣流軌跡。",
  "cast_flavor": "指尖劃過，帶起一陣不安的旋風。"
}

{
  "pick": 1,
  "name_zh": "暗影襲擊",
  "concept": "透過標記的縫隙滲透黑暗，將敵人擊倒在陰影之中。",
  "cast_flavor": "當印記顯現，漆黑的重壓便會隨之而來。"
}

{
  "pick": 2,
  "name_zh": "狂飆氣流",
  "concept": "引動空氣的劇烈擾動，使周遭的元素與毒霧隨之擴散。",
  "cast_flavor": "狂風捲動了地表的毒素與霜凍，將混沌向外推開。"
}

{
  "pick": 2,
  "name_zh": "旋風擴散",
  "concept": "透過空氣的流動，讓周遭的環境變化向外擴大。",
  "cast_flavor": "氣流捲動了地表的變化，將範圍內的影響向四周擴散。"
}

{
  "pick": 1,
  "name_zh": "俯瞰之風",
