  "cast_flavor": "黑暗從法器中噴湧而出，將目標的身影徹底吞沒。"
}

{
  "pick": 0,
  "name_zh": "雷霆之紋",
  "concept": "於地面與空間交織出閃爍的電光符文。",
  "cast_flavor": "指尖劃過虛空，迸發出的電光在目標足下留下了跳動的符號。"
}

{
  "pick": 2,
  "name_zh": "重擊衝撞",
  "concept": "利用武器的重量與衝勁，將敵人強行撞離原位。",
  "cast_flavor": "重兵器劃破空氣，伴隨著沉悶的撞擊聲將對手推開。"
}

{
  "pick": 0,
