  "cast_flavor": "光輝從雲端墜落，使受害者在眩目中顯露致命的破綻。"
}

{
  "pick": 0,
  "name_zh": "俯瞰之威",
  "concept": "在制高點俯瞰戰場，將神聖的威壓轉化為對敵人的直接打擊。",
  "cast_flavor": "光輝自上方籠罩，使敵人顯露出致命的破綻。"
}

{
  "pick": 1,
  "name_zh": "閃爍之標",
  "concept": "以雷光為媒介，將不穩定的電性烙入對手體內。",
  "cast_flavor": "光點在目標身上炸裂，留下了無法抹去的電光印記。"
}

{
  "pick": 1,
